package com.rodentcontrol.customer;
import android.os.Bundle;import android.graphics.BitmapFactory;import android.view.View;import android.widget.*;import androidx.appcompat.app.AppCompatActivity;import java.util.concurrent.Executors;
public class SiteDetailActivity extends AppCompatActivity{
 TextView detail;ImageView floorImage;Button floorButton;int siteId;org.json.JSONObject firstPlan;protected void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_detail);detail=findViewById(R.id.detail);floorImage=findViewById(R.id.floorImage);floorButton=findViewById(R.id.floorButton);siteId=getIntent().getIntExtra("id",0);int id=siteId;Executors.newSingleThreadExecutor().execute(()->{try{org.json.JSONObject r=Api.site(this,id),s=r.getJSONObject("site");org.json.JSONArray p=r.getJSONArray("control_points"),sc=r.getJSONArray("schedules"),fp=r.getJSONArray("floor_plans");StringBuilder x=new StringBuilder();x.append(s.optString("name")).append("\n").append(s.optString("address")).append("\n\nSơ đồ: ").append(fp.length()).append(" phiên bản\nĐiểm kiểm soát: ").append(p.length()).append("\n\nCác điểm kiểm soát:\n");for(int j=0;j<p.length();j++){org.json.JSONObject q=p.getJSONObject(j);x.append(q.optString("point_number")).append(" — ").append(q.optString("zone_name","")).append(" — ").append(q.optString("status")).append(" — ").append(q.optString("asset_code","chưa gắn hộp")).append("\n");}x.append("\nLịch dịch vụ gần đây:\n");for(int i=0;i<Math.min(20,sc.length());i++){org.json.JSONObject q=sc.getJSONObject(i);x.append(q.optString("scheduled_date")).append(" — ").append(q.optString("status")).append("\n");}firstPlan=fp.length()>0?fp.getJSONObject(0):null;runOnUiThread(()->{detail.setText(x.toString());if(firstPlan!=null){floorButton.setVisibility(View.VISIBLE);floorButton.setOnClickListener(v->loadPlan(firstPlan.optInt("id")));}});}catch(Exception e){runOnUiThread(()->detail.setText(e.getMessage()));}});}
 void loadPlan(int planId){new Thread(()->{try{byte[] bytes=Api.floorPlan(this,siteId,planId);android.graphics.Bitmap b=BitmapFactory.decodeByteArray(bytes,0,bytes.length);if(b==null){runOnUiThread(()->Toast.makeText(this,"Sơ đồ PDF hoặc định dạng chưa hỗ trợ xem trực tiếp trên màn hình này.",Toast.LENGTH_LONG).show());return;}runOnUiThread(()->{floorImage.setImageBitmap(b);floorImage.setVisibility(View.VISIBLE);});}catch(Exception e){runOnUiThread(()->Toast.makeText(this,e.getMessage(),Toast.LENGTH_LONG).show());}}).start();}
}
